public void insert()
{
    next insert();

    WrkCtrTable wrkCtrTable = WrkCtrTable::find(this.WrkCtrId, true);

    if (wrkCtrTable)
    {
        wrkCtrTable.avaInitFromResourceGroup();
        wrkCtrTable.update();
    }
}

public static WrkCtrResourceGroupResource avaFind(WrkCtrId _wrkCtrId)
{
    WrkCtrResourceGroupResource wrkCtrResourceGroupResource = null;

    select firstonly wrkCtrResourceGroupResource
        where wrkCtrResourceGroupResource.WrkCtrId == _wrkCtrId;

    return wrkCtrResourceGroupResource;
}
